int original_data = 10;
int *data_pointer;

// Address translation/mapping established
data_pointer = &original_data;

// Indirect read via pointer (Dereferencing)
int current_value = *data_pointer; // current_value is 10

// Indirect write (manipulation via mapped address)
*data_pointer = 500;

// original_data is now 500
// Pointers enable pass-by-reference
void change(int *p) { *p += 1; }
change(&original_data); // original_data is 501
change(data_pointer);   // original_data is 502
data_pointer = NULL;
